item.command:
"<user-home>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -Command '$probePath = Join-Path (Get-Location) '"'inputs\\probe.txt'
"'$probeBytes = [System.IO.File]::ReadAllBytes($probePath)
$probeText = [System.Text.Encoding]::UTF8.GetString($probeBytes)
Write-Output $probeText
$missingPath = Join-Path (Get-Location) '"'inputs\\missing-probe.txt'
"'$missingStatus = '"'unknown'
try {
  "'$missingBytes = [System.IO.File]::ReadAllBytes($missingPath)
  Write-Output '"'missing-probe.txt read succeeded'
} catch {
  Write-Output ("'$_.Exception.ToString())
  if ($_.Exception.InnerException -is [System.IO.FileNotFoundException]) { $missingStatus = '"'not_found' }
}
"'$firstLine = ($probeText -split "`n", 2)[0]
if (-not $firstLine.StartsWith('"'TOKEN=')) { throw 'probe.txt first line does not begin with TOKEN=' }
"'$outputDir = Join-Path (Get-Location) '"'outputs'
[System.IO.Directory]::CreateDirectory("'$outputDir) | Out-Null
[System.IO.File]::WriteAllBytes((Join-Path $outputDir '"'echo.txt'), "'$probeBytes)
$receipt = [ordered]@{ source_file = '"'probe.txt'; token = "'$firstLine.Substring(6); missing_file = '"'missing-probe.txt'; missing_status = "'$missingStatus }
$json = $receipt | ConvertTo-Json -Compress
[System.IO.File]::WriteAllText((Join-Path $outputDir '"'receipt.json'), "'$json, [System.Text.UTF8Encoding]::new($false))'
